mapper.update:
UPDATE TB_BOARD
   SET BOARD_TITLE = #{boardTitle}
     , BOARD_CONTENT = #{boardContent}
     , BOARD_CATEGORY = #{boardCategory}
 WHERE BOARD_NO = #{boardNo}
   AND REF_MNO = (SELECT MEMBER_NO FROM TB_MEMBER WHERE MEMBER_ID = #{boardWriter})

UPDATE TB_ATTACHMENT
   SET ATTACHMENT_PATH = #{attachmentPath}
     , ORIGINAL_FILE_NAME = #{originName} 
     , MODIFIED_FILE_NAME = #{changeName} 
     , REG_DATE = SYSDATE               
 WHERE REF_BNO = #{refBno}
   AND STATUS = 'Y'

mapper.select:
SELECT * FROM ( SELECT B.BOARD_NO AS boardNo, B.BOARD_TITLE AS boardTitle, B.BOARD_CONTENT AS boardContent, B.BOARD_CATEGORY AS boardCategory, C.CATEGORY_NAME AS categoryName,
B.REF_MNO AS boardAuthor, M.MEMBER_ID AS memberId, M.MEMBER_IMAGE AS memberImage,
A.ATTACHMENT_PATH AS attachmentPath,
R.REGION_NO AS regionNo, R.REGION_NAME AS regionName,
B.REG_DATE AS regDate,
ROW_NUMBER() OVER (ORDER BY B.BOARD_NO DESC) AS RN FROM TB_BOARD B JOIN TB_MEMBER M ON B.REF_MNO = M.MEMBER_NO JOIN TB_CATEGORY C ON B.BOARD_CATEGORY = C.CATEGORY_NO LEFT JOIN TB_REGION R ON M.REF_RNO = R.REGION_NO LEFT JOIN ( SELECT REF_BNO, MIN(ATTACHMENT_PATH) AS ATTACHMENT_PATH FROM TB_ATTACHMENT WHERE STATUS = 'Y' GROUP BY REF_BNO ) A ON A.REF_BNO = B.BOARD_NO WHERE B.STATUS = 'Y' AND B.BOARD_CATEGORY LIKE #{category}
AND B.BOARD_NO < #{fetchOffset}
) WHERE RN <= #{limit}

mapper.insert:
INSERT INTO TB_BOARD 
(
    BOARD_NO
  , REF_MNO
  , BOARD_CATEGORY
  , BOARD_TITLE
  , BOARD_CONTENT
  , REG_DATE
  , STATUS  
)
VALUES
(
    SEQ_BNO.NEXTVAL
  , #{boardAuthor}
  , #{boardCategory}
  , #{boardTitle}
  , #{boardContent}
  , SYSDATE
  , 'Y'  
)

INSERT INTO TB_ATTACHMENT (
      FILE_NO fileNo
    , REF_BNO refBno
    , ATTACHMENT_PATH attachmentPath
    , REG_DATE regDate
    , STATUS 
) VALUES (
      SEQ_FNO.NEXTVAL
    , #{boardNo}
    , #{file}
    , SYSDATE
    , 'Y'
)
